INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('e962616c-1cfa-5eb8-bd8f-8a6564695178','TEXT','The Tiny Ferry — A Different Day','When Zoe first became interested in the model ferry, the task at the river workshop looked routine. Yet on Wednesday, an unexpected problem appeared. A hurried solution would have been possible, but Zoe suspected that the first explanation was too simple. Instead, Zoe treated the problem as a small investigation.
